import {randomUUID} from 'node:crypto';
import {
  Catch,
  HttpException,
  type ArgumentsHost,
  type ExceptionFilter,
  type NestMiddleware,
} from '@nestjs/common';
import type {NextFunction, Request, Response} from 'express';
import {ApiErrorEnvelopeSchema, type ApiErrorEnvelope, type ErrorCode} from '@me-palnadu/contracts';
import {ApiError, statusForErrorCode} from './api-error.js';
import {mapPersistenceError} from './persistence-error.js';

/**
 * Every response that carries an error uses this envelope. It is generated by the
 * contracts schema and then parsed back through it, so a malformed envelope is a
 * bug that fails in tests rather than a shape a client has to guess.
 */

export interface RequestWithId extends Request {
  id?: string;
}

/** Attaches a correlation id to every request, and echoes it back. */
export class RequestIdMiddleware implements NestMiddleware {
  use(request: RequestWithId, response: Response, next: NextFunction): void {
    const incoming = request.headers['x-request-id'];
    const id =
      typeof incoming === 'string' && incoming.length > 0 && incoming.length <= 128
        ? incoming
        : randomUUID();
    request.id = id;
    response.setHeader('x-request-id', id);
    next();
  }
}

const isApiError = (error: unknown): error is ApiError =>
  error instanceof ApiError ||
  (error instanceof HttpException &&
    error.getResponse() instanceof Object &&
    'code' in (error.getResponse() as object));

@Catch()
export class ApiExceptionFilter implements ExceptionFilter {
  private readonly logger = new ApiExceptionFilterLogger();

  catch(error: unknown, host: ArgumentsHost): void {
    const http = host.switchToHttp();
    const request = http.getRequest<RequestWithId>();
    const response = http.getResponse<Response>();
    const requestId = request.id ?? 'unknown';

    const mapped = isApiError(error)
      ? {error: error as ApiError, logMessage: `${error.name}: ${error.message}`}
      : mapPersistenceError(error);

    if (mapped.error.code === 'INTERNAL_ERROR') {
      // Log the safe-to-log detail once; never forward it to the client.
      this.logger.error({requestId, detail: mapped.logMessage});
    } else if (mapped.error.code === 'RATE_LIMITED') {
      this.logger.warn({requestId, detail: mapped.logMessage});
    }

    const envelope = buildEnvelope(mapped.error, requestId);
    response.status(statusForErrorCode(mapped.error.code)).json(envelope);
  }
}

export const buildEnvelope = (error: ApiError, requestId: string): ApiErrorEnvelope => {
  const candidate = {
    error: {
      code: error.code,
      message: error.message,
      requestId,
      ...(error.details === undefined ? {} : {details: error.details}),
    },
  } satisfies ApiErrorEnvelope;

  // Parsing our own output through the contract makes drift impossible to ship.
  return ApiErrorEnvelopeSchema.parse(candidate);
};

/** Minimal structured logger; swapped for pino when log shipping is configured. */
class ApiExceptionFilterLogger {
  error(context: Record<string, unknown>): void {
    console.error(JSON.stringify({level: 'error', ...context}));
  }

  warn(context: Record<string, unknown>): void {
    console.warn(JSON.stringify({level: 'warn', ...context}));
  }
}

export type {ErrorCode};
